/**
 * Check if a given object implements the DirectHolderItem interface.
 */
export function instanceOfDirectHolderItem(value) {
    if (!("entityName" in value) || value["entityName"] === undefined)
        return false;
    return true;
}
export function DirectHolderItemFromJSON(json) {
    return DirectHolderItemFromJSONTyped(json, false);
}
export function DirectHolderItemFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        entityName: json["entity_name"],
        dateReported: json["date_reported"] == null ? undefined : json["date_reported"],
        shares: json["shares"] == null ? undefined : json["shares"],
        value: json["value"] == null ? undefined : json["value"],
        percentHeld: json["percent_held"] == null ? undefined : json["percent_held"],
    };
}
export function DirectHolderItemToJSON(json) {
    return DirectHolderItemToJSONTyped(json, false);
}
export function DirectHolderItemToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        entity_name: value["entityName"],
        date_reported: value["dateReported"],
        shares: value["shares"],
        value: value["value"],
        percent_held: value["percentHeld"],
    };
}
